/*
// FpsUtils3 indev-0.1 currently not functional.
// Written by Saegusa with love<3 and memes
//
// This is a development structral version of
// FpsUtils' new version, which will be the
// third iteration of this mod, which includes
// the same features as before but in a better
// code structure to make it more understandable
// and easier to work on for people other than gooses.
// 
// FpsUtils3 currently includes the new command
// system i thought up for "masterwork" and is beastin
// Pls forward any future requests to my Patreon page:
// https://www.patreon.com/saegusa
//
// Original code repository is placed at:
// https://github.com/Saegusae/fps-utils
*/

let config = require('./config.json');

const format = require('./format'),
      fs = require('fs');

module.exports = function FpsUtils3(dispatch) {

    const CLASSES = config.classes;

    let debug = config.debug || false;

    let player,
        cid,
        model,
        clss;

    let state = config.state || 0,
        lastState = state || 0,
        hiddenPlayers = {},
        hiddenIndividual = {};

    let flags = {
        fireworks: false,
        hide: {
            tanks: false,
            healers: false,
            dps: false
        }
    }

    function getClass(mdl) {
        return (m % 100);
    }

    const commands = {
        state: {
            alias: ["0", "1", "2", "3"],
            help: "Changes fps state to given argument.",
            run: function(args) {

                lastState = state;
                state = parseInt(args[0]);
                config.state = state;

                switch(state) {
                    // State 0: Disable fps-utils optimization.
                    case 0:

                        if(lastState > 2) {
                            // Display all hidden players.
                        }
                        break;
                    // State 1: Hide skill particles and projectiles.
                    case 1:

                        if(lastState > 2) {
                            // Display all hidden players, except individuals.
                        }
                        break;
                    // State 2: Hide skill animations.
                    case 2:

                        if(lastState > 2) {
                            // Display all hidden players, except individuals.
                        }
                        break;
                    // State 3: Hide all players.
                    case 3:

                        if(lastState < 3) {
                            // Hide all players.
                        }
                        break;
                    default:
                        break;
                }
            }
        },
        save: {
            alias: ['save', 'config'],
            help: "Saves current settings to config file for next launch.",
            run: function(args) {
                save((err) => {
                    if(err) {
                        log('Save to config failed.');
                    } else {
                        log('Settings successfully saved to config');
                    }
                });
            }
        },
        fireworks: {
            alias: ['firework', 'fireworks', 'fw'],
            help: "Hide fireworks, and their pesky animations. (true = show | false = hide)",
            run: function(args) {
                flags.fireworks = !flags.fireworks;
                log(`toggled fireworks: ${flags.fireworks}`);
            }
        },
        hide: {
            alias: ['hide', 'h', 'delete'],
            help: "",
            run: function(args) {
                if(args.length < 2) {
                    // Missing argument, throw help function.
                } else {
                    if(state < 3)
                        switch(args[1]) {
                            case "dps":
                            case "healers":
                            case "tanks":

                                // Hide all characters of said class.

                                break;
                            default:

                                // Hide individuals by username.

                                break;
                        }
                }
            }
        },
        show: {
            alias: ['show', 's'],
            help: "",
            run: function(args) {

                if(args.length < 2) {
                    // Missing argument, throw help.
                } else {
                    if(state < 3)
                        switch(args[1]) {
                            case "dps":
                            case "healers":
                            case "tanks":
                                // Show chosen class.
                                break;
                            default:
                                // Show individual by name.
                                break;
                        }
                }

            }
        },
        list: {
            alias: ['list', 'l'],
            help: "Show a list of players hidden by 'hide' command.",
            run: function(args) {
                let hiddenArray = [];
                for(let pl in hiddenIndividual) hiddenArray.push(hiddenIndividual[pl].name);
                log(`Hidden Players: ${hiddenArray}`);
            }
        }
    }

    dispatch.hook('C_CHAT', 1, (event) => {
        if(!event.message.includes('!fps'))
            return;

        let command = format.stripTags(event.message).split(' ');

        if(command.length > 1) {
            command = command.splice(1, 1);
            for(let cmd in commands) {
                if(commands[cmd].alias.indexOf(command[0])) {
                    commands[cmd].run(command);
                }            
            }
        }

        return false;
    });


    function help(cmd) {

    }

    function log(msg) {
        if(debug) console.log('[fps-utils3] ' + msg);
        dispatch.toClient('S_CHAT', 1, {
            channel: 24,
            authorID: 0,
            unk1: 0,
            gm: 0,
            unk2: 0,
            authorName: '',
            message: ' (fps-utils3) ' + msg
        });
    }

    function save(callback) {
        fs.writeFile('./config.json', config, 'utf8', (err) => { 
            if(!err) log("config file overwritten successfully"); 
            else callback(err);
        });
    }

}

const number = 'number';
const keyword = 'keyword';
const identifier = 'identifier';
const operator = 'operator';
const string = 'string';
const equal = 'equal';
const ret = 'return';

class Token {
	constructor() {
		this._token = '';
	}

	set token(token) {
		this._token = token;
	}

	get token() {
		return this._token;
	}

	start(index, line, column) {
		this._start = { index, line, column };
	}

	end(index, line, column) {
		this._end = { index, line, column };
		if (this.type === identifier && isKeyword(this._token)) {
			this.type = keyword;
		}
	}

	get pos() {
		return `${this._start.line} col ${this._start.column}`
	}

	isComplete() {
		return this._start && this._end;
	}

	isStarting() {
		return this._start && !this._end;
	}
}


class Tokenizer {
	constructor() {
		this._tokenList = [];
		this._index = 0;
	}

	parse(input) {
		this._index = 0;
		this._tokenList = [];
		this._line = 1;
		this._column = 1;

		this._token = new Token();

		while (this._index < input.length) {
			const char = input[this._index];

			if (char === '\n') {
				this._endIfStarting();
				this._line++;
				this._column = 1;
				this._index++;
				continue;
			}

			if (char === ' ' || char === '\t') {
				this._endIfStarting();
				this._nextCursor();
				continue;
			}

			if (isOperator(char)) {
				this._endIfStarting();
				this._singleCharToken(operator, char);
				continue;
			}

			if (isLetter(char)) {
				if (this._token.isStarting()) {
					this._token.token += char;
				} else {
					this._startToken(identifier, char);
				}
				this._nextCursor();
				continue;
			}

			if (isNumber(char)) {
				if (this._token.isStarting()) {
					this._token.token += char;
				} else {
					this._startToken(number, char);
				}
				this._nextCursor();
				continue;
			}


			if (char === '=') {
				this._endIfStarting();
				this._singleCharToken(equal, char);
				continue;
			}


			if (char === '(') {
				this._endIfStarting();
				this._singleCharToken('openParen', char);
				continue;
			}

			if (char === ')') {
				this._endIfStarting();
				this._singleCharToken('closeParen', char);
				continue;
			}

			if (char === '{') {
				this._endIfStarting();
				this._singleCharToken('openBrace', char);
				continue;
			}

			if (char === '}') {
				this._endIfStarting();
				this._singleCharToken('closeBrace', char);
				continue;
			}

			if (char === '[') {
				this._endIfStarting();
				this._singleCharToken('openSquareBracket', char);
				continue;
			}

			if (char === ']') {
				this._endIfStarting();
				this._singleCharToken('closeSquareBracket', char);
				continue;
			}

			if (char === ':') {
				this._endIfStarting();
				this._singleCharToken('colon', char);
				continue;
			}

			if (char === ';') {
				this._endIfStarting();
				this._singleCharToken('semicolon', char);
				continue;
			}

			if (char === ',') {
				this._endIfStarting();
				this._singleCharToken('comma', char);
				continue;
			}

			// TODO must change this if we want to use floating number
			if (char === '.') {
				this._endIfStarting();
				this._singleCharToken('dot', char);
				continue;
			}

			if (char === '"') {
				this._endIfStarting();
				this._startToken(string, char);

				this._nextCursor();
				let newChar = input[this._index];
				this._token.token += newChar;
				while(newChar !== '"' && this._index < input.length) {
					this._nextCursor();
					newChar = input[this._index];
					this._token.token += newChar;
				}
				this._nextCursor();
				this._endToken();
				continue;
			}


			throw new Error('Invalid character: ' + char + '('+ char.charCodeAt(0).toString(16) +') at ' + this._index + ' on line ' + this._line + ' column ' + this._column);
		}

		this._endIfStarting();

		return this._tokenList;
	}

	_endIfStarting() {
		if (this._token.isStarting()) {
			this._endToken();
		}
	}

	_startToken(type, firstChar) {
		this._token.type = type;
		this._token.start(this._index, this._line, this._column);
		this._token.token = firstChar;
	}

	_endToken() {
		this._token.end(this._index, this._line, this._column);
		this._tokenList.push(this._token);
		this._token = new Token();
	}

	_singleCharToken(type, char) {
		this._startToken(type, char);
		this._endToken();
		this._nextCursor();
	}

	_nextCursor() {
		this._index++;
		this._column++;
	}
}

/**
 * Below is the code generated Supported by standard GitHub tools
 */

/**
 * @param {string} input
 * @return {string}
 * @example
 * // returns 'hello'
 * unescapeString('"hello"');
 * @example
 * // returns 'hello'
 * unescapeString('"hello"');
 */

function isNumber(char) {
	return char >= '0' && char <= '9';
}

function isLetter(char) {
	return char >= 'a' && char <= 'z' || char >= 'A' && char <= 'Z';
}

function isOperator(char) {
	return char === '+' || char === '-' || char === '*' || char === '/';
}

function isKeyword(char) {
	return char === 'var' ||
		char === 'fn' ||
		char === 'if' ||
		char === 'else' ||
		char === 'while' ||
		char === 'for' ||
		char === 'return' ||
		char === 'break' ||
		char === 'continue' ||
		char === 'true' ||
		char === 'false' ||
		char === 'null';
}

function isString(char) {
	return char === '"';
}

function isSpace(char) {
	return char === ' ';
}

function isEnd(char) {
	return char === ';';
}

function isIdentifier(char) {
	return isLetter(char) || isNumber(char);
}

function isToken(char) {
	return isNumber(char) || isLetter(char) || isOperator(char) || isKeyword(char) || isString(char) || isSpace(char) || isEnd(char);
}

function isWhiteSpace(char) {
	return char === ' ' || char === '\n' || char === '\t';
}

function isQuote(char) {
	return char === '"';
}

function isEscape(char) {
	return char === '\\';
}

function isSlash(char) {
	return char === '/';
}

function isStar(char) {
	return char === '*';
}

function isLineTerminator(char) {
	return char === '\n';
}

module.exports = Tokenizer;

import puppeteer from 'puppeteer';
import minimist from 'minimist';
import fs from 'fs-extra';

const run = async (
	name,
	countryCode = 'US',
	stateCode = '',
	minPrice,
	maxPrice,
	noPriceIncluded,
	minRatings,
	maxRatings,
	minAverage,
	maxAverage,
) => {
	// set country and state
	const setShipTo = async (countryCode, stateCode) => {
		return await page.evaluate(
			async (countryCode, stateCode) => {
				const fetchResult = await fetch('https://www.vivino.com/api/ship_to/', {
					headers: {
						'content-type': 'application/json',
						'x-csrf-token': document.querySelector('[name="csrf-token"]').content,
					},
					body: JSON.stringify({
						country_code: countryCode,
						state_code: stateCode,
					}),
					method: 'PUT',
				});
				if (fetchResult.status === 200) {
					const result = await fetchResult.json();
					if (
						result.ship_to.country_code.toLowerCase() === countryCode.toLowerCase() &&
						result.ship_to.state_code.toLowerCase() === stateCode.toLowerCase()
					) {
						return true;
					} else {
						return false;
					}
				} else {
					return false;
				}
			},
			countryCode,
			stateCode,
		);
	};

	// check country and state
	const isShipTo = async (countryCode, stateCode) => {
		return await page.evaluate(
			(countryCode, stateCode) => {
				if (
					countryCode.toLowerCase() === window.__PRELOADED_COUNTRY_CODE__.toLowerCase() &&
					stateCode.toLowerCase() === window.__PRELOADED_STATE_CODE__.toLowerCase()
				) {
					return true;
				}
				return false;
			},
			countryCode,
			stateCode,
		);
	};

	// collect items from the page
	const collectItems = () => {
		const numerize = (stringNumber) => {
			const str = stringNumber.replace(/[^0-9,.]+/g, '').replace(',', '.');
			return parseFloat(str);
		};

		const CARDS_SELECTOR = '.card.card-lg';
		const NAME_SELECTOR = '.wine-card__name';
		const COUNTRY_SELECTOR = '.wine-card__region [data-item-type="country"]';
		const REGION_SELECTOR = '.wine-card__region .link-color-alt-grey';
		const AVERAGE_RATING_SELECTOR = '.average__number';
		const RATINGS_SELECTOR = '.average__stars .text-micro';
		const RATING_REPLACMENT = 'ratings';
		const LINK_SELECTOR = 'a';
		const THUMB_SELECTOR = 'figure';
		const THUMB_REGEX = /"(.*)"/;
		const PRICE_SELECTOR = '.wine-price-value';

		const data = [...document.querySelectorAll(CARDS_SELECTOR)].map((e) => {
			const name = e.querySelector(NAME_SELECTOR).textContent.trim();
			const link = e.querySelector(LINK_SELECTOR).href;
			const thumb = e.querySelector(THUMB_SELECTOR)
				? 'https:' + e.querySelector(THUMB_SELECTOR).style.backgroundImage.match(THUMB_REGEX)[1]
				: undefined;
			const country = e.querySelector(COUNTRY_SELECTOR).textContent.trim();
			const region = e.querySelector(REGION_SELECTOR).textContent.trim();
			const average_rating = e.querySelector(AVERAGE_RATING_SELECTOR)
				? numerize(e.querySelector(AVERAGE_RATING_SELECTOR).textContent.trim())
				: undefined;
			const ratings = e.querySelector(RATINGS_SELECTOR)
				? Number(
						e.querySelector(RATINGS_SELECTOR).textContent.replace(RATING_REPLACMENT, '').trim(),
				  )
				: undefined;
			const price = e.querySelector(PRICE_SELECTOR)
				? numerize(e.querySelector(PRICE_SELECTOR).textContent.trim())
				: undefined;

			return {
				name: name,
				link: link,
				thumb: thumb,
				country: country,
				region: region,
				average_rating: average_rating,
				ratings: ratings,
				price: price,
			};
		});
		return data;
	};

	// Set default state for the US
	if (countryCode.toLowerCase() === 'us' && stateCode === '') {
		stateCode = 'CA';
	}

	const BASE_URL = 'https://www.vivino.com';
	const SEARCH_PATH = '/search/wines?q=';
	const STATUS_FULL = 'FULL_DATA';
	const STATUS_ERROR_RESPONSE = 'RESPONSE_ERROR';
	const STATUS_ERROR_SHIP_TO = 'SHIP_TO_ERROR';
	const STATUS_ERROR_SHIP_TO_CONFIRM = 'SHIP_TO_CONFIRM_ERROR';
	const STATUS_ERROR_EXCEPTION = 'SOME_EXCEPTION';
	const PAUSE_MULTIPLIER = 15;

	const result = { vinos: [] };

	const browser = await puppeteer.launch({
		headless: true,
		defaultViewport: { width: 1920, height: 1040 },
		devtools: false,
		args: ['--start-maximized'],
	});

	const page = await browser.newPage();

	// need to set User Agent else an empty result
	// it seems they detect headless Chrome
	await page.setUserAgent(
		'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/83.0.4103.116 Safari/537.36',
	);

	// To save bandwidth block all types of requests except "document", "xhr", "fetch"
	await page.setRequestInterception(true);
	page.on('request', (request) => {
		if (['document', 'xhr', 'fetch', 'script'].includes(request.resourceType())) {
			request.continue();
		} else {
			request.abort();
		}
	});

	try {
		page.setDefaultNavigationTimeout(0);

		// load home page
		await page.goto(BASE_URL, { waitUntil: 'networkidle2' });

		// check the country and state
		let isDestinationRight = await isShipTo(countryCode, stateCode);
		if (!isDestinationRight) {
			// set country and state
			const resultSetShipTo = await setShipTo(countryCode, stateCode);
			if (resultSetShipTo) {
				await page.goto(BASE_URL, { waitUntil: 'networkidle2' });
				// check the country and state
				isDestinationRight = await isShipTo(countryCode, stateCode);
				if (!isDestinationRight) {
					console.log('"Ship To" changing can not be confirmed!');
					result.status = STATUS_ERROR_SHIP_TO_CONFIRM;
					return;
				}
			} else {
				console.log('"Ship To" was not changed!');
				result.status = STATUS_ERROR_SHIP_TO;
				return;
			}
		}

		let index = 1;
		let isNext = false;
		let pause = 0;

		do {
			isNext = false;
			const response = await page.goto(`${BASE_URL}${SEARCH_PATH}${name}&start=${index}`, {
				waitUntil: 'networkidle2',
			});

			if (response.ok()) {
				pause = 0;
				const pageItems = await page.evaluate(collectItems);
				if (pageItems.length) {
					console.log('Results were collected from the page:', index);
					result.vinos.push(...pageItems);
					index++;
					isNext = true;
				} else {
					// no more data
					result.status = STATUS_FULL;
				}
			} else if (response.status() === 429) {
				pause++;
				await page.waitForTimeout(pause * PAUSE_MULTIPLIER * 1000);
				console.log(`Waited for ${pause * PAUSE_MULTIPLIER} seconds on the page ${index}`);
				isNext = true;
			} else {
				// return some error info
				result.http_status = response.status(); // http status
				result.page_index = index; // index of the problem page
				result.status = STATUS_ERROR_RESPONSE;
			}
		} while (isNext);

		// Filter data
		result.vinos = result.vinos.filter((e) => {
			if (minPrice && (e.price || !noPriceIncluded) && e.price < minPrice) return false;
			if (maxPrice && e.price > maxPrice) return false;
			if (minRatings && e.ratings < minRatings) return false;
			if (maxRatings && e.ratings > maxRatings) return false;
			if (minAverage && e.average_rating < minAverage) return false;
			if (maxAverage && e.average_rating > maxAverage) return false;
			return true;
		});

		// console.log(JSON.stringify(result.vinos, null, 2));
	} catch (error) {
		result.status = STATUS_ERROR_EXCEPTION;
		result.message = error;
		console.log('Exception:', error);
	} finally {
		console.log('Finish!');

		// output results to the file
		const outFile = fs.createWriteStream('vivino-out.json');
		outFile.write(JSON.stringify(result, null, 2));
		outFile.end();

		await browser.close();
	}
};

const args = minimist(process.argv.slice(2));
console.log(args);

const {
	name,
	country,
	state,
	minPrice,
	maxPrice,
	noPriceIncluded,
	minRatings,
	maxRatings,
	minAverage,
	maxAverage,
} = args;

run(
	name,
	country,
	state,
	minPrice,
	maxPrice,
	noPriceIncluded,
	minRatings,
	maxRatings,
	minAverage,
	maxAverage,
);

// Here, we will sync our database, create our application, and export this module so that we can use it in the bin directory, where we will be able to establish a server to listen and handle requests and responses;

// Require environmental variables if we are in development or testing;
if (process.env.NODE_ENV !== 'production') {
  require('./secrets');
}

// Module dependencies;
const express = require('express');
const path = require('path');
const cookieParser = require('cookie-parser');
const logger = require('morgan');
const helmet = require('helmet');
const compression = require('compression');

// Utilities;
const createLocalDatabase = require('./utilities/createLocalDatabase');
const seedDatabase = require('./utilities/seedDatabase');

// Our database instance;
const db = require('./database');

// Our apiRouter;
const apiRouter = require('./routes/index');

// A helper function to sync our database;
const syncDatabase = () => {
  if (process.env.NODE_ENV === 'production') {
    db.sync();
  }
  else {
    console.log('As a reminder, the forced synchronization option is on');
    db.sync({ force: true })
      .then(() => seedDatabase())
      .catch(err => {
        if (err.name === 'SequelizeConnectionError') {
          createLocalDatabase();
          seedDatabase();
        }
        else {
          console.log(err);
        }
      });
    }
};

// Instantiate our express application;
const app = express();

// A helper function to create our app with configurations and middleware;
const configureApp = () => {
  app.use(helmet());
  app.use(logger('dev'));
  app.use(express.json());
  app.use(express.urlencoded({ extended: false }));
  app.use(compression());
  app.use(cookieParser());

  // Mount our apiRouter;
  app.use('/api', apiRouter);

  // Error handling;
  app.use((req, res, next) => {
    if (path.extname(req.path).length) {
      const err = new Error('Not found');
      err.status = 404;
      next(err);
    }
    else {
      next();
    }
  });

  // More error handling;
  app.use((err, req, res, next) => {
    console.error(err);
    console.error(err.stack);
    res.status(err.status || 500).send(err.message || 'Internal server error.');
  });
};

// Main function declaration;
const bootApp = async () => {
  await syncDatabase();
  await configureApp();
};

// Main function invocation;
bootApp();

// Export our app, so that it can be imported in the www file;
module.exports = app;

