    res.toString = toString;
    pth.abs = pathClone(res);
    return res;
}
function l2c(x1, y1, x2, y2) {
    return [x1, y1, x2, y2, x2, y2];
}
function q2c(x1, y1, ax, ay, x2, y2) {
