import React, { StrictMode } from 'react';
import { render, cleanup } from '@testing-library/react';

import { useAsyncTask, useAsyncRun, useAsyncTaskTimeout } from '../src/index';

// FIXME we should fake timers
// jest.useFakeTimers();
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

describe('basic spec', () => {
  afterEach(cleanup);

  it('should have a function', () => {
    expect(useAsyncTask).toBeDefined();
  });

  it('should create a component with timeout', async () => {
    const Waiting = ({ abort }) => (
      <div>
        Waiting...
        <button type="button" onClick={abort}>Abort</button>
      </div>
    );
    const renderHi = () => <h1>Hi</h1>;
    const DelayedMessage = ({ delay }) => {
      const asyncTask = useAsyncTaskTimeout(renderHi, delay, [renderHi, delay]);
      useAsyncRun(asyncTask);
      const {
        pending,
        error,
        result,
        abort,
      } = asyncTask;
      if (error) return <div>Error: {error.message}</div>;
      if (pending) return <Waiting abort={abort} />;
      return <div>Result: {result}</div>;
    };
    const App = () => (
      <StrictMode>
        <div>
          <DelayedMessage delay={300} />
          <DelayedMessage delay={100} />
        </div>
      </StrictMode>
    );
    const { container } = render(<App />);
    expect(container).toMatchSnapshot();
    // jest.advanceTimersByTime(100);
    await sleep(100);
    expect(container).toMatchSnapshot();
    // jest.advanceTimersByTime(200);
    await sleep(200);
    expect(container).toMatchSnapshot();
  });
});

// ==UserScript==
// @name         Pass für alle
// @namespace    https://passfuralle.se
// @version      2.17
// @description  Ett snabbt och enkelt sätt att boka passtid
// @author       Jonk
// @match        https://*.nemoq.se/Booking/Booking/*
// @grant        none
// @require      https://code.jquery.com/jquery-3.6.0.min.js#sha256-/xUj+3OJU5yExlq6GSYGSHk7tPXikynS7ogEvDej/m4=
// @require      https://cdnjs.cloudflare.com/ajax/libs/ion-sound/3.0.7/js/ion.sound.min.js

// ==/UserScript==

(function() {

    var jQuery = window.jQuery;
    var ion = window.ion;

    // Constants
    log('Set constants');
    var dateFrom = today();
    var dateTo = '2022-12-24';
    var autoConfirm = true;
    var acceptOffice = '';

    var datePickerElem = jQuery('#datepicker');
    if (!localStorage.getItem('TimeSearch')) {
        log('Set start date');
        datePickerElem.val(dateFrom);
    }

    jQuery('input[name="TimeSearchButton"]').on('click', function () {
        log('Start time search');
        localStorage.setItem('TimeSearch', 'TimeSearchButton');
        localStorage.removeItem('responseText');
    });
    jQuery('input[name="TimeSearchFirstAvailableButton"]').on('click', function () {
        log('Start time search first available');
        localStorage.setItem('TimeSearch', 'TimeSearchFirstAvailableButton');
        localStorage.removeItem('responseText');
    });
    jQuery('a[href*="/Booking/Booking/Previous/skane?id="]').on('click', function() {
        log('Clear time search');
        localStorage.removeItem('TimeSearch');
        localStorage.removeItem('responseText');
    });
    jQuery('body').on('click', 'a.cancel-search', function() {
        log('Cancel search');
        jQuery('html, body').css('overflow', 'visible');
        localStorage.removeItem('TimeSearch');
        localStorage.removeItem('responseText');
        location.reload();
    });

    setButtonTexts();
    jQuery("#SectionId").change(function() {
        setButtonTexts();
    });

    // Find a time
    if (jQuery('.controls .btn.btn-primary[name="TimeSearchButton"]').length || jQuery('.controls .btn.btn-primary[name="TimeSearchFirstAvailableButton"]').length) {
        log('Time search view');

        var datePickerVal = datePickerElem.val();

        if (Date.parse(datePickerVal) < Date.parse(dateFrom)) {
            log('Start later than today');
            datePickerElem.val(dateFrom);
        }

        if (localStorage.getItem('TimeSearch')) {
            log('Start time search');
            loader();
            captcha();
            if (Date.parse(datePickerVal) > Date.parse(dateTo) || (localStorage.getItem('TimeSearch') == 'TimeSearchButton' && Date.parse(datePickerVal) < Date.parse(dateFrom))) {
                log('Start over time search');
                datePickerElem.val(dateFrom);
                setTimeout(function () {
                    jQuery('input[name="' + localStorage.getItem('TimeSearch') + '"]').click();
                }, timeSearchTimeout());
            } else {
                log('Check for slot');
                var availableTimeSlots = jQuery('.pointer.timecell.text-center[data-function="timeTableCell"][aria-label!="Bokad"]');

                // Filter accepted passport offices
                if(acceptOffice && acceptOffice.length) {
                    availableTimeSlots = availableTimeSlots.filter(function() {
                        var office = jQuery(this).closest(".timetable-cells").attr("headers");
                        return acceptOffice.split(",").some(function(acceptedOffice) {
                            return office.includes(acceptedOffice)
                        });
                    }) 
                }

                if (availableTimeSlots.length) {
                    log('Time found');
                    availableTimeSlots.first().click();
                    var timeSelectionText;
                    if (jQuery.trim(jQuery('#timeSelectionText').text()).length) {
                        timeSelectionText = jQuery('#timeSelectionText').text();
                    } else {
                        timeSelectionText = availableTimeSlots.first().data('fromdatetime');
                    }
                    var responseText = jQuery.trim(jQuery('#selectionText').text() + ' ' + jQuery('#sectionSelectionText').text() + ' ' + timeSelectionText);
                    localStorage.setItem('responseText', responseText);
                    if (autoConfirm || confirm(responseText)) {
                        log('Auto confirm');
                        jQuery('#booking-next').click();
                    }
                } else {
                    log('No time found');
                    setTimeout(function () {
                        log('Check next');
                        if (jQuery('#nextweek').length) {
                            log('Check next week');
                            jQuery('#nextweek').attr('name','TimeSearchButton');
                            jQuery('#nextweek').click();
                        } else if (jQuery('.btn.btn-link.pull-right').attr('name','KeyTimeSearchNextDayButton').length) {
                            log('Check next day');
                            jQuery('.btn.btn-link.pull-right').attr('name','KeyTimeSearchNextDayButton').click();
                        }
                    }, timeSearchTimeout());
                }
            }
        }
    }

    // Time found
    if (jQuery('.breadcrumb li').length == 6) {
        log('Book time view');
        jQuery('.breadcrumb').after('<h2 style="text-align:center;padding:20px;">' + localStorage.getItem('responseText') + '</h2>'); 
        localStorage.removeItem('TimeSearch');
        localStorage.removeItem('responseText');
        playSound('bell_ring');
    }

    function log(log) {
        console.log(log);
    }

    function timeSearchTimeout() {
        log('Set timeout');
        var timeout = 1000;
        /*
        if (localStorage.getItem('TimeSearch') == 'TimeSearchFirstAvailableButton') {
            log('Long timeout');
            timeout = 15000;
        } else {
            log('Normal timeout');
        }
        */
        return timeout;
    }

    function today() {
        var today = new Date();
        return today.toISOString().slice(0,10);
    }

    function setButtonTexts() {
        log('Set button texts');
        jQuery('input[name="TimeSearchFirstAvailableButton"]').val('Första lediga tid innan ' + dateTo);
        if (jQuery("#SectionId option:selected").val() == 0) {
            jQuery('input[name="TimeSearchButton"]').val('Sök tid mellan ' + dateFrom + ' och ' + dateTo);
            jQuery('input[name="TimeSearchButton"]').css('display', '');
        } else {
            jQuery('input[name="TimeSearchButton"]').val('Funkar inte än');
            jQuery('input[name="TimeSearchButton"]').css('display', 'none');
        }
    }

    function playSound(sound) {
        // http://ionden.com/a/plugins/ion.sound/en.html
        ion.sound({
            sounds: [
                {name: sound}
            ],

            // main config
            path: "https://cdnjs.cloudflare.com/ajax/libs/ion-sound/3.0.7/sounds/",
            preload: true,
            multiplay: true,
            volume: 0.9
        });

        // play sound
        ion.sound.play(sound);
    }

    function loader() {
        if (!jQuery('.loading').length) {
            jQuery('html, body').css('overflow', 'hidden');
            jQuery('body').append('<div class="loading" style="display: flex; width: 100vw; height: 100vh; position: absolute; left: 0; top: 0; justify-content: center; align-items: center;z-index: 999; background: rgba(255,255,255,.6);"><div style="background: #eee; padding: 20px; border-radius: 20px; width: 200px; height: 200px; display: flex; justify-content: center; align-items: center; flex-direction: column; z-index: 999;"><div>Söker efter tid</div><div class="loader-animation">.</div><a href="#" class="cancel-search">Avbryt</a></div></div>');
            loaderAnimation();
        }
    }

    function captcha() {
        if (jQuery('.mtcaptcha').length) {
            playSound('light_bulb_breaking');
            localStorage.removeItem('TimeSearch');
            localStorage.removeItem('responseText');
            setTimeout(function () {
                location.href = location.href;
            }, 1000);
        }
    }

    function loaderAnimation() {
        jQuery('.loader-animation').html('.');
        setTimeout(function () {
            jQuery('.loader-animation').html('..');
        }, 250);
        setTimeout(function () {
            jQuery('.loader-animation').html('...');
        }, 500);
        setTimeout(function () {
            loaderAnimation();
        }, 750);
    }

})();

/**
 * Class for rendering charts in Obsidian.
 * To be used with DataviewJS, Obsidian Charts and CustomJS plugins
 * @author Olivier C <olo06@hotmail.fr>
 */
 class DvCharts {

    /**
     * Render a chart on a daily basis with a custom attribute extracted from dailies pages
     * @param {object} args - object to pass containing properties used
     * @param {object} args.dv - dataview object to perform queries
     * @param {object} args.context - context to be set to **this**, used to render chart in place
     * @param {string} args.daysPath - path to Daily notes
     * @param {string} args.dayFormat - format of daily pages in Moment format
     * @param {string} args.attr - attribute to query and render the value
     * @param {string} args.label - label to display in chart for corresponding attr
     * @param {number} args.limit - numbers of last pages containing values to display
     */
    renderSingleAttrChart(args) {

        const {
            dv,
            context,
            daysPath = '"01-Notes/Journal"',
            dayFormat = 'YYYY-MM-DD',
            attr,
            label,
            limit = 30
        } = args;

        let days = dv.pages(daysPath)
            .where(p => p[attr] && moment(p.file.name, dayFormat).isValid())
            .sort(p => p.file.name)
            .filter((p, i, arr) => i >= arr.length - limit);

        let dates = [], attrData = [];
        days.forEach(p => {
            dates.push(p.file.name);
            attrData.push(p[attr]);
        });

        const chartData = {
            type: 'line',
            data: {
                labels: dates,
                datasets: [{
                    label,
                    data: attrData,
                    backgroundColor: 'rgba(85, 174, 229, 0.2)',
                    borderColor: 'rgba(85, 174, 229, 1)',
                    borderWidth: 1,
                    fill: true,
                    tension: 0.2
                }],
            }
        }

        window.renderChart(chartData, context.container);
    }

    /**
     * Render a chart on a weekly basis from the specified date
     * @param {object} args - object to pass containing properties used
     * @param {object} args.dv - dataview object to perform queries
     * @param {object} args.context - context to be set to **this**, used to render chart in place
     * @param {string} args.daysPath - path to Daily notes
     * @param {string} args.dayFormat - format of daily pages in Luxon format
     * @param {string} args.attributes - object with keys as attributes to query and values as metadatas
     * @param {object} args.template - default template for completing datasets metadatas
     * @param {string} args.type - set it to **'average'** to display average data in chart
     * @param {string} args.date - date in YYYY-MM-DD format from which weekly days will be retrieved
     */
    renderWeeklyChart(args) {

        const {
            dv,
            context,
            daysPath = '""',
            dayFormat = 'yyyy-MM-dd',
            template = {
                label: "Default",
                backgroundColor: 'rgba(255, 99, 132, 0.2)',
                borderColor: 'rgba(255, 99, 132, 1)',
                borderWidth: 1,
                fill: true,
                tension: 0.2
            },
            attributes,
            type,
            date
        } = args;

        const datasets = (() => {
            const startOfWeek = dv.date("sow");
            const getWeeklyDay = dayNum => dv.pages(`"${daysPath}"`).find(
                p => p.file.name == startOfWeek.plus({ days: dayNum }).toFormat(dayFormat));
            const weeklydays = Array.from({ length: 7 }, (c, i) => getWeeklyDay(i) || 0);
            const getData = (attr, props) => weeklydays.map(p =>
                (type == 'average') ? (p[attr] / props.average * 100) || 0 : p[attr]);
            let datasets = {};

            for (let [attr, props] of Object.entries(attributes)) {
                datasets[attr] = Object.assign({}, template, props, {data: getData(attr, props)});
            }

            return Object.values(datasets);
        })();

        const chartData = {
            type: 'line',
            data: {
                labels: ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"],
                datasets,
            }
        }

        window.renderChart(chartData, context.container);
    }
}

import inquirer from "inquirer";
import chalk from "chalk";

export default async n => {
	if (n === undefined) {
		const answers = await inquirer.prompt([
			{
				name: "n",
				message: "N?",
				validate(value) {
					if (/^\d+$/.test(value)) {
						// Is a number
						return true;
					} else {
						// Error message
						return "Value of n is not a positive integer.";
					}
				}
			}
		]);
		n = answers.n;
	}

	n = parseInt(n);

	if (isNaN(n) || n < 1) {
		console.log(chalk.yellowBright("Value of n is not a positive integer."));
		process.exit(1);
	}

	const value = fibonacci(n);
	console.log(
		`Fibonacci for n=${chalk.blueBright(n)} = ${chalk.blueBright(value)}!`
	);
};

// High performance fibonacci from https://medium.com/developers-writing/fibonacci-sequence-algorithm-in-javascript-b253dc7e320e
function fibonacci(num, memo = {}) {
	if (memo[num]) return memo[num];
	if (num <= 1) return 1;

	return (memo[num] = fibonacci(num - 1, memo) + fibonacci(num - 2, memo));
}

