'use strict';

const ReactionHandler = require('eris-reactions');

/**
 * @typedef {import('eris').EmbedBase} EmbedBase
 * @typedef {import('eris').Message} Message
 * @typedef {Object} PaginationOptions An optional options object for overwriting defaults
 * @property {Boolean} [showPageNumbers] Whether or not to show the current page index over the embed. Defaults to: true
 * @property {Boolean} [extendedButtons] Whether or not to show extended control buttons besides standard pagination (First & Last page, deleting)
 * @property {Boolean} [cycling] Cycle through all embeds jumping from the first page to the last page on going back and from the last page to the first page going forth. Defaults to: false
 * @property {Number} [maxMatches] How often the reaction handler should listen for a reaction (How often the paginator can be used). Defaults to: 50. Maximum: 100
 * @property {Number} [timeout] How long the paginator should work before the reaction listener times out. Defaults to: 300000ms (5 minutes). Maximum: 900000ms (15 minutes)
 * @property {String} [deleteButton] Emoji which should be used as the delete button. This MUST be a unicode emoji! Defaults to: 🗑
 * @property {String} [firstButton] Emoji which should be used as the first page button. This MUST be a unicode emoji! Defaults to: ⏮
 * @property {String} [lastButton] Emoji which should be used as the last page button. This MUST be a unicode emoji! Defaults to: ⏭
 * @property {String} [backButton] Emoji which should be used as the back button. This MUST be a unicode emoji! Defaults to: ⬅
 * @property {String} [forthButton] Emoji which should be used as the forth button. This MUST be a unicode emoji! Defaults to: ➡
 * @property {Number} [startPage] Which page of the submitted embed array should be shown first. Defaults to: 1 (The 1st page / element in the array)
 */
/**
 * Embed Pagination class
 * @class PaginationEmbed
 * @classdesc Handles the creation, listening and updating of paginated Rich Embeds
 */
class PaginationEmbed {
    /**
     * Constructor for the Embed Paginator
     * @param {Message} message A message object emitted from a messageCreate event coming from Eris, used as an invoker. If sent by the client, the message will be edited.
     * @param {EmbedBase[]} pages An array containing all embed objects 
     * @param {PaginationOptions} [options] An optional options object for overwriting defaults
     */
    constructor(message, pages = [], options = {}) {
        this.pages      = pages;
        this.invoker    = message;
        this.options    = options;
        this.delete     = options.deleteButton  || '🗑';
        this.firstPage  = options.firstButton   || '⏮';
        this.lastPage   = options.lastButton    || '⏭';
        this.back       = options.backButton    || '⬅';
        this.forth      = options.forthButton   || '➡';
        this.page       = options.startPage     || 1;
        this.maxMatches = options.maxMatches    || 50;
        this.timeout    = options.timeout       || 300000;
        this.cycling    = options.cycling       || false
        this.showPages  = (typeof options.showPageNumbers !== 'undefined') ? options.showPageNumbers : true;
        this.advanced   = (typeof options.extendedButtons !== 'undefined') ? options.extendedButtons : false;
    }

    /**
     * Runs a set of initialization checks, sets up the reaction listener for continuous listening and displays the initial Embed
     * @async
     */
    async initialize() {
        if (this.pages.length < 2) {
            return Promise.reject(new Error('A Pagination Embed must contain at least 2 pages!'));
        }

        if (this.page < 1 || this.page > this.pages.length) {
            return Promise.reject(new Error(`Invalid start page! Must be between 1 (first) and ${this.pages.length} (last)`));
        }

        if (this.maxMatches > 100) {
            return Promise.reject(new Error('Maximum amount of page changes exceeded! Must be under 100!'));
        }

        if (this.timeout > 900000) {
            return Promise.reject(new Error('Embed Timeout too high! Maximum pagination lifespan allowed is 15 minutes (900000 ms)!'));
        }

        const messageContent = {
            content: (this.showPages) ? `Page **${this.page}** of **${this.pages.length}**` : undefined,
            embed: this.pages[this.page - 1]
        }

        if (this.invoker.author.id === this.invoker._client.user.id) {
            this.message = await this.invoker.edit(messageContent);
        } else {
            this.message = await this.invoker.channel.createMessage(messageContent)
        }

        this.handler = new ReactionHandler.continuousReactionStream(this.message, (userID) => userID === this.invoker.author.id, false, { maxMatches: this.maxMatches, time: this.timeout });

        if (this.advanced) {
            await this.message.addReaction(this.firstPage);
            await this.message.addReaction(this.back);
            await this.message.addReaction(this.forth);
            await this.message.addReaction(this.lastPage);
            await this.message.addReaction(this.delete);
        } else {
            await this.message.addReaction(this.back);
            await this.message.addReaction(this.forth);
        }
    }

    /**
     * Updates the embed's content with the new page
     */
    update() {
        this.message.edit({
            content: (this.showPages) ? `Page **${this.page}** of **${this.pages.length}**` : undefined,
            embed: this.pages[this.page - 1]
        });
    }

    /**
     * Check if the client can remove the reaction
     * @returns {Boolean}
     */
    checkPerms() {
        return this.message.channel.guild && this.message.channel.permissionsOf(this.message._client.user.id).has('manageMessages');
    }

    /**
     * Main method handling the reaction listening and content updating
     */
    run() {
        this.handler.on('reacted', async (event) => {
            switch (event.emoji.name) {
                case this.firstPage: {
                    if (this.advanced) {
                        if (this.checkPerms()) {
                            await this.message.removeReaction(this.firstPage, this.invoker.author.id);
                        }

                        if (this.page > 1) {
                            this.page = 1;
                            this.update();
                        }

                        break;
                    }
                }

                case this.back: {
                    if (this.checkPerms()) {
                        await this.message.removeReaction(this.back, this.invoker.author.id);
                    }

                    if (this.page > 1) {
                        this.page--;
                        this.update();
                    } else if (this.page === 1 && this.cycling === true) {
                        this.page = this.pages.length;
                        this.update();
                    }

                    break;
                }

                case this.forth: {
                    if (this.checkPerms()) {
                        await this.message.removeReaction(this.forth, this.invoker.author.id);
                    }

                    if (this.page < this.pages.length) {
                        this.page++;
                        this.update();
                    } else if (this.page === this.pages.length && this.cycling === true) {
                        this.page = 1;
                        this.update();
                    }

                    break;
                }

                case this.lastPage: {
                    if (this.advanced) {
                        if (this.checkPerms()) {
                            await this.message.removeReaction(this.lastPage, this.invoker.author.id);
                        }

                        if (this.page < this.pages.length) {
                            this.page = this.pages.length;
                            this.update();
                        }

                        break;
                    }

                    break;
                }

                case this.delete: {
                    if (this.advanced) {
                        return new Promise((resolve, reject) => {
                            if (this.checkPerms()) {
                                this.message.removeReactions().then(() => {
                                    resolve();
                                });
                            } else {
                                reject(new Error('Insufficient permissions to remove reactions'))
                            }
                        });
                    }

                    break;
                }
            }
        });
    }
}

module.exports = {
    /**
     * Create an Embed Paginator
     * 
     * @param {Message} message A message object emitted from a messageCreate event coming from Eris, used as an invoker. If sent by the client, the message will be edited.
     * @param {EmbedBase[]} pages An array containing all embed objects 
     * @param {PaginationOptions} [options] An optional options object for overwriting defaults
     */
    createPaginationEmbed: async (message, pages, options) => {
        const paginationEmbed = new PaginationEmbed(message, pages, options);
        await paginationEmbed.initialize();
        paginationEmbed.run();

        return Promise.resolve(paginationEmbed.message);
    }
};

const express = require('express');
const { requireClient, requireOwnershipOrAdmin, validateInput, SecurityLogger } = require('../middleware/AuthMiddleware');
const database = require('../utils/database');
const { v4: uuidv4 } = require('uuid');
const router = express.Router();

// Aided with basic GitHub coding tools - Client Schedule Menu Routes with OWASP Security

// Middleware pentru validare input pe toate rutele client
router.use(validateInput);
router.use(requireClient);

/**
 * GET /api/client/schedule
 * Meniul principal de programări pentru clienți
 * OWASP 4.5.3 - Client privilege separation
 */
router.get('/schedule', (req, res) => {
    try {
        SecurityLogger.logRoleAccess(req.user.userId, 'client', '/schedule', true, req.ip);

        // Citește doar programările utilizatorului curent
        const userSchedules = getUserSchedules(req.user.userId);

        res.json({
            access: 'personal_only',
            role: 'client',
            redirectTo: '/client/schedule-menu',
            user: {
                id: req.user.userId,
                email: req.user.email,
                name: req.user.name,
                role: 'client'
            },
            schedules: userSchedules,
            canAddSchedule: true,
            canViewOthers: false,
            canEditOwn: true,
            canDeleteOwn: true,
            availableServices: [
                'Inspecția tehnică periodică',
                'Verificare instalație GPL',
                'Verificare sisteme frânare',
                'Control emisii poluante',
                'Verificare instalații electrice',
                'Inspecție completă vehicul'
            ],
            availableTimeSlots: [
                '08:00', '09:00', '10:00', '11:00',
                '12:00', '13:00', '14:00', '15:00', '16:00'
            ],
            message: 'Acces acordat la meniul personal de programări'
        });

    } catch (error) {
        console.error('Eroare accesare meniu programări:', error);
        SecurityLogger.logSuspiciousActivity(req.user?.userId, 'SCHEDULE_MENU_ERROR', {
            error: error.message,
            ip: req.ip
        });
        res.status(500).json({
            error: 'Eroare la accesarea meniului de programări.'
        });
    }
});

/**
 * POST /api/client/schedule
 * Adaugă o programare nouă pentru client
 * OWASP 4.5.4 - Secure object creation with UUID
 */
router.post('/schedule', (req, res) => {
    try {
        const { date, time, service, vehicleDetails, notes } = req.body;

        // Validare input obligatorii
        if (!date || !time || !service) {
            return res.status(400).json({
                error: 'Câmpurile data, ora și serviciul sunt obligatorii.'
            });
        }

        // Validare format dată
        const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
        if (!dateRegex.test(date)) {
            return res.status(400).json({
                error: 'Format dată invalid. Folosește YYYY-MM-DD.'
            });
        }

        // Validare că data este în viitor
        const scheduleDate = new Date(date + 'T' + time);
        if (scheduleDate <= new Date()) {
            return res.status(400).json({
                error: 'Data programării trebuie să fie în viitor.'
            });
        }

        // Validare ore disponibile
        const validTimes = ['08:00', '09:00', '10:00', '11:00', '12:00', '13:00', '14:00', '15:00', '16:00'];
        if (!validTimes.includes(time)) {
            return res.status(400).json({
                error: 'Ora selectată nu este disponibilă.'
            });
        }

        // Verifică disponibilitatea orei
        if (isTimeSlotTaken(date, time)) {
            return res.status(409).json({
                error: 'Ora selectată este deja ocupată. Te rugăm să alegi altă oră.'
            });
        }

        // Creează programarea cu UUID pentru securitate
        const scheduleId = uuidv4();
        const newSchedule = {
            id: scheduleId,
            userId: req.user.userId,
            userEmail: req.user.email,
            date,
            time,
            service,
            vehicleDetails: vehicleDetails || {},
            notes: notes || '',
            status: 'confirmed',
            createdAt: new Date().toISOString(),
            updatedAt: new Date().toISOString()
        };

        // Salvează în database
        saveSchedule(newSchedule);

        SecurityLogger.logRoleAccess(req.user.userId, 'client', '/schedule/create', true, req.ip);

        res.status(201).json({
            message: 'Programare adăugată cu succes!',
            scheduleId,
            schedule: newSchedule,
            status: 'confirmed',
            confirmationNumber: `PROG-${Date.now()}-${scheduleId.substring(0, 8).toUpperCase()}`
        });

    } catch (error) {
        console.error('Eroare creare programare:', error);
        SecurityLogger.logSuspiciousActivity(req.user?.userId, 'SCHEDULE_CREATE_ERROR', {
            error: error.message,
            ip: req.ip
        });
        res.status(500).json({
            error: 'Eroare la crearea programării.'
        });
    }
});

/**
 * GET /api/client/schedule/:scheduleId
 * Vizualizează detaliile unei programări (doar proprietarul)
 * OWASP 4.5.4 - IDOR protection
 */
router.get('/schedule/:scheduleId', (req, res) => {
    try {
        const { scheduleId } = req.params;

        if (!scheduleId) {
            return res.status(400).json({
                error: 'ID programare este obligatoriu.'
            });
        }

        const schedule = getScheduleById(scheduleId);

        if (!schedule) {
            return res.status(404).json({
                error: 'Programarea nu a fost găsită.'
            });
        }

        // Verifică că utilizatorul poate accesa această programare
        if (schedule.userId !== req.user.userId) {
            SecurityLogger.logSuspiciousActivity(req.user.userId, 'UNAUTHORIZED_SCHEDULE_ACCESS', {
                attemptedScheduleId: scheduleId,
                scheduleOwnerId: schedule.userId,
                ip: req.ip
            });

            return res.status(403).json({
                error: 'Nu poți accesa programarea altui utilizator.'
            });
        }

        res.json({
            schedule,
            canEdit: true,
            canDelete: true,
            canReschedule: schedule.status === 'confirmed'
        });

    } catch (error) {
        console.error('Eroare încărcare programare:', error);
        res.status(500).json({
            error: 'Eroare la încărcarea programării.'
        });
    }
});

/**
 * PUT /api/client/schedule/:scheduleId
 * Editează o programare existentă (doar proprietarul)
 * OWASP 4.5.4 - Secure object modification
 */
router.put('/schedule/:scheduleId', (req, res) => {
    try {
        const { scheduleId } = req.params;
        const { date, time, service, vehicleDetails, notes } = req.body;

        const existingSchedule = getScheduleById(scheduleId);

        if (!existingSchedule) {
            return res.status(404).json({
                error: 'Programarea nu a fost găsită.'
            });
        }

        // Verifică ownership
        if (existingSchedule.userId !== req.user.userId) {
            SecurityLogger.logSuspiciousActivity(req.user.userId, 'UNAUTHORIZED_SCHEDULE_EDIT', {
                attemptedScheduleId: scheduleId,
                scheduleOwnerId: existingSchedule.userId,
                ip: req.ip
            });

            return res.status(403).json({
                error: 'Nu poți modifica programarea altui utilizator.'
            });
        }

        // Verifică dacă programarea poate fi modificată
        if (existingSchedule.status === 'completed' || existingSchedule.status === 'cancelled') {
            return res.status(400).json({
                error: 'Nu poți modifica o programare completată sau anulată.'
            });
        }

        // Validări pentru noile date (dacă sunt furnizate)
        if (date && time) {
            const newScheduleDate = new Date(date + 'T' + time);
            if (newScheduleDate <= new Date()) {
                return res.status(400).json({
                    error: 'Noua dată trebuie să fie în viitor.'
                });
            }

            // Verifică disponibilitatea noii ore (exceptând programarea curentă)
            if (isTimeSlotTaken(date, time, scheduleId)) {
                return res.status(409).json({
                    error: 'Ora selectată este deja ocupată.'
                });
            }
        }

        // Actualizează programarea
        const updatedSchedule = {
            ...existingSchedule,
            date: date || existingSchedule.date,
            time: time || existingSchedule.time,
            service: service || existingSchedule.service,
            vehicleDetails: vehicleDetails || existingSchedule.vehicleDetails,
            notes: notes || existingSchedule.notes,
            updatedAt: new Date().toISOString()
        };

        updateSchedule(scheduleId, updatedSchedule);

        res.json({
            message: 'Programare actualizată cu succes!',
            schedule: updatedSchedule
        });

    } catch (error) {
        console.error('Eroare actualizare programare:', error);
        res.status(500).json({
            error: 'Eroare la actualizarea programării.'
        });
    }
});

/**
 * DELETE /api/client/schedule/:scheduleId
 * Șterge o programare (doar proprietarul)
 * OWASP 4.5.4 - Secure object deletion
 */
router.delete('/schedule/:scheduleId', (req, res) => {
    try {
        const { scheduleId } = req.params;

        const existingSchedule = getScheduleById(scheduleId);

        if (!existingSchedule) {
            return res.status(404).json({
                error: 'Programarea nu a fost găsită.'
            });
        }

        // Verifică ownership
        if (existingSchedule.userId !== req.user.userId) {
            SecurityLogger.logSuspiciousActivity(req.user.userId, 'UNAUTHORIZED_SCHEDULE_DELETE', {
                attemptedScheduleId: scheduleId,
                scheduleOwnerId: existingSchedule.userId,
                ip: req.ip
            });

            return res.status(403).json({
                error: 'Nu poți șterge programarea altui utilizator.'
            });
        }

        // Șterge programarea
        deleteSchedule(scheduleId);

        SecurityLogger.logRoleAccess(req.user.userId, 'client', `/schedule/delete/${scheduleId}`, true, req.ip);

        res.json({
            message: 'Programare ștearsă cu succes!',
            deletedScheduleId: scheduleId,
            deletedAt: new Date().toISOString()
        });

    } catch (error) {
        console.error('Eroare ștergere programare:', error);
        res.status(500).json({
            error: 'Eroare la ștergerea programării.'
        });
    }
});

