            filter: true,
            sortable: true,
            resizable: true,
        },
        {
            headerName: "Moderator Exists",
            field: "CollegeModeratorExists",
            filter: true,
            sortable: true,
            resizable: true,
        },
        {
            headerName: "Page Created",
            field: "CollegePageCreated",
            filter: true,
            sortable: true,
            resizable: true,
        },
    ];

    return (
        <Box>
            <Grid
                rowData={data}
                columnDefs={columnDefs}
