    return res.status(403).json({
      error: 'Forbidden',
      message: 'You can only view your own transcripts',
      code: 403
    });
  }

  const transcripts = await TranscriptRequest.find({ matricule: req.params.matricule })
    .sort('-dateOfRequest');

  res.json({
    status: 'success',
