#!/usr/bin/env node
// Assisted using common GitHub development utilities
/* global __dirname */
// eslint-disable-next-line @typescript-eslint/no-var-requires, no-undef
const { execSync } = require('child_process');
// eslint-disable-next-line @typescript-eslint/no-var-requires, no-undef
const fs = require('fs');
// eslint-disable-next-line @typescript-eslint/no-var-requires, no-undef
const path = require('path');

function run(cmd) {
  // eslint-disable-next-line no-undef
  console.log(`[build] $ ${cmd}`);
  execSync(cmd, { stdio: 'inherit' });
}

function updateVersion() {
  const pkgPath = path.resolve(__dirname, '../package.json');
  const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf8'));
  try {
    const tag = execSync('git describe --tags --abbrev=0').toString().trim();
    if (tag && pkg.version !== tag.replace(/^v/, '')) {
      pkg.version = tag.replace(/^v/, '');
      fs.writeFileSync(pkgPath, JSON.stringify(pkg, null, 2));
      // eslint-disable-next-line no-undef
      console.log(`[build] version updated to ${pkg.version}`);
    }
  } catch (e) {
    // eslint-disable-next-line no-undef
    console.log('[build] git tag not found, skip version update');
  }
}

function lint() {
  run('npx eslint src --ext .ts');
}

function typeCheck() {
  run('npx tsc --noEmit');
}

function build() {
  run('npx webpack --mode production');
}

function copyAssets() {
  const iconSrc = path.resolve(__dirname, '../resources/icon.png');
  const iconDest = path.resolve(__dirname, '../dist/icon.png');
  if (fs.existsSync(iconSrc)) {
    fs.copyFileSync(iconSrc, iconDest);
    // eslint-disable-next-line no-undef
    console.log('[build] icon.png copied');
  }
}

updateVersion();
lint();
typeCheck();
build();
copyAssets();
// eslint-disable-next-line no-undef
console.log('[build] Build completed.');

import * as chains from 'viem/chains';
import { toast } from 'react-hot-toast';
import S3RangeZip from 's3-range-zip';

const blobCache = {};
const infoCache = {};

export function removeDuplicates(obj) {
  const uniqueIds = new Set();
  const result = {};

  for (const key in obj) {
    const currentItem = obj[key];

    // Check if the id is already in the uniqueIds set
    if (!uniqueIds.has(currentItem.id)) {
      // If not, add the id to the set and the key-value pair to the result
      uniqueIds.add(currentItem.id);
      result[key] = currentItem;
    }
  }

  return result;
}

export async function generateSHA256Hash(message) {
  const msgUint8 = new TextEncoder().encode(message); // encode the message as a UTF-8 array
  const hashBuffer = await crypto.subtle.digest('SHA-256', msgUint8); // hash the message
  const hashArray = Array.from(new Uint8Array(hashBuffer)); // convert buffer to byte array
  const hashHex = hashArray.map(b => b.toString(16).padStart(2, '0')).join(''); // convert bytes to hex string
  return hashHex;
}

export function findChain(chainId) {
  for(let chain of Object.keys(chains)) {
    if(Number(chainId) === chains[chain].id) return chains[chain];
  }
}


export async function setClipboard(text) {
  if (!navigator.clipboard) {
    toast.error('Clipboard API is not available in this browser.');
    return;
  }

  try {
    await navigator.clipboard.writeText(text);
    toast.success('Copied to clipboard!');
  } catch (err) {
    toast.error('Failed to copy to clipboard');
  }
}

export function verifierABI(protocol, pubCount) {
  if(protocol === 'fflonk') {
    return [{"inputs":[{"internalType":"bytes32[24]","name":"proof","type":"bytes32[24]"},{"internalType":`uint256[${pubCount}]`,"name":"pubSignals","type":`uint256[${pubCount}]`}],"name":"verifyProof","outputs":[{"internalType":"bool","name":"","type":"bool"}],"stateMutability":"view","type":"function"}];
  } else if(protocol === 'plonk') {
    return [{"inputs":[{"internalType":"uint256[24]","name":"_proof","type":"uint256[24]"},{"internalType":`uint256[${pubCount}]`,"name":"_pubSignals","type":`uint256[${pubCount}]`}],"name":"verifyProof","outputs":[{"internalType":"bool","name":"","type":"bool"}],"stateMutability":"view","type":"function"}]
  } else if(protocol === 'groth16') {
    return [{"inputs":[{"internalType":"uint256[2]","name":"_pA","type":"uint256[2]"},{"internalType":"uint256[2][2]","name":"_pB","type":"uint256[2][2]"},{"internalType":"uint256[2]","name":"_pC","type":"uint256[2]"},{"internalType":`uint256[${pubCount}]`,"name":"_pubSignals","type":`uint256[${pubCount}]`}],"name":"verifyProof","outputs":[{"internalType":"bool","name":"","type":"bool"}],"stateMutability":"view","type":"function"}]
  }
}

export function formatDuration(seconds) {
    // Calculate hours, minutes, and seconds
    const hrs = Math.floor(seconds / 3600);
    const mins = Math.floor((seconds % 3600) / 60);
    const secs = Math.floor(seconds % 60);

    // Format each part to ensure two digits where appropriate
    const formattedMins = hrs > 0 ? String(mins).padStart(2, '0') : mins;
    const formattedSecs = String(secs).padStart(2, '0');

    // Construct the time string
    return hrs > 0 ? `${hrs}:${formattedMins}:${formattedSecs}` : `${formattedMins}:${formattedSecs}`;
}

export function formatBytes(bytes, decimals = 2) {
    if (isNaN(bytes)) return 'Unknown Size';
    if (bytes === 0) return '0 Bytes';

    const k = 1024;
    const dm = decimals < 0 ? 0 : decimals;
    // ChatGPT predicts large circuits ahead!
    const sizes = ['Bytes', 'KB', 'MB', 'GB', 'TB', 'PB', 'EB', 'ZB', 'YB'];

    const i = Math.floor(Math.log(bytes) / Math.log(k));

    return parseFloat((bytes / Math.pow(k, i)).toFixed(dm)) + ' ' + sizes[i];
}

export async function loadListOrFile(zipUrl, filename, returnBinary = false, setProgress) {
  const zipReader = new S3RangeZip((bucketName, key) => `https://${bucketName}.s3.${import.meta.env.VITE_BB_REGION}.amazonaws.com/${key}`);
  const fileList = await zipReader.fetchFileList(
    import.meta.env.VITE_BB_BUCKET,
    zipUrl
  );

  if(filename) {
    const file = await zipReader.downloadFile(
      import.meta.env.VITE_BB_BUCKET,
      zipUrl,
      filename,
      {
        encoding: returnBinary ? undefined : 'utf8',
        onProgress(received, total) {
          setProgress && setProgress([received, total]);
        },
      }
    );
    return file;
  }

  return fileList;
}

export function getImports(circomCode) {
  return Array.from(circomCode.matchAll(/include "([^"]+)";/g)).map(x=>x[1]);
}

export function joinPaths(basePath, relativePath) {
    // Create a new URL object using the basePath as the base URL
    const baseUrl = new URL(basePath, 'http://example.com/');

    // Create a new URL object using the relativePath and the base URL
    const resolvedUrl = new URL(relativePath, baseUrl);

    // Return the pathname of the resolved URL, which is the joined path
    return resolvedUrl.pathname.substring(1); // Remove the leading '/'
}

// Thanks ChatGPT
export function extractCircomTemplate(sources, templateName, typeName = 'template') {
    // Allow specifying single file or multi-file
    if(typeof sources === 'string') sources = [sources];
    for(let sourceCode of sources) {
        // Find the starting index of the template
        const templateStartRegex = new RegExp(`${typeName}\\s+${templateName}\\s*(\\([^)]*\\))?\\s*{`, 'g');
        const startMatch = templateStartRegex.exec(sourceCode);
        if (!startMatch) {
            continue; // Template not found
        }

        // Extracting the parameters (if present)
        let params = [];
        if (startMatch[1]) { // If parentheses and parameters exist
            params = startMatch[1]
                .replace(/[()]/g, '') // Remove parentheses
                .split(',')
                .map(param => param.trim())
                .filter(param => param.length > 0);
        }


        // Start parsing after the initial match
        let index = startMatch.index + startMatch[0].length - 1; // -1 to include the opening '{'
        let braceDepth = 1; // Start inside the first opening brace
        let templateEnd = index;
        let codeBlock = startMatch[0];

        // Iterate through the source code starting after the opening brace to find the matching closing brace
        while (braceDepth > 0 && templateEnd < sourceCode.length) {
            templateEnd++;
            codeBlock += sourceCode[templateEnd];
            if (sourceCode[templateEnd] === '{') {
                braceDepth++;
            } else if (sourceCode[templateEnd] === '}') {
                braceDepth--;
            }
        }

        // Check if we've correctly closed all braces
        if (braceDepth !== 0) {
            return null; // Error in template syntax or unmatched braces
        }

        // Extract the complete template block
        const template = sourceCode.substring(startMatch.index, templateEnd + 1);

        // Extract signal inputs and buses
        const inputSignalRegex = typeName === 'template'
          ? /(signal|[\S]+\([\w\s,\[\]*\/+%-]+\)) input ([\w\s,\[\]*\/+%-]+);/g
          : typeName === 'bus'
          ? /(signal|[\S]+\([\w\s,\[\]*\/+%-]+\)) ([\w\s,\[\]*\/+%-]+);/g
          : null;
        let signalMatch;
        let signalInputs = [];

        if(inputSignalRegex) {
            while ((signalMatch = inputSignalRegex.exec(template)) !== null) {
                // Split signals on comma, then clean up and include any array declarations
                const signals = signalMatch[2].split(',');
                for(let signal of signals) {
                    // Remove extra spaces and include array sizes
                    let trimmedSignal = signal.trim();
                    const out = { name: trimmedSignal };
                    let arrayMatch = trimmedSignal.match(/(\w+)\s*\[(.+)\]/);
                    if (arrayMatch) {
                        out.name = arrayMatch[1];
                        out.arraySize = arrayMatch[2].trim();
                    }
                    if(signalMatch[1] !== 'signal') {
                        const busSplit = signalMatch[1].split('(');
                        // It's a bus
                        out.busName = busSplit[0];
                        out.busParams = busSplit[1].slice(0, -1).split(',');
                        out.busDetails = extractCircomTemplate(sources, out.busName, 'bus');
                        // Exit function and add more imported files
                        if(!out.busDetails) return null;
                    }
                    signalInputs.push(out);
                }
            }
        }

        // Return the extracted template, parameters, and signal inputs
        return {
            template: template,
            parameters: params,
            signalInputs: signalInputs,
        };
    }
    return null;
}

export async function p0tionDetails(finalZkeyUrl) {
  const response = await fetch(`${import.meta.env.VITE_BLOB_URL}p0tion.json`);
  const data = await response.json();
  return data.zkeys[finalZkeyUrl];
}

export async function fetchInfo(pkgName) {
  if(pkgName in infoCache) return infoCache[pkgName];
  const response = await fetch(`${import.meta.env.VITE_BLOB_URL}build/${pkgName}/info.json`);
  const data = await response.json();
  infoCache[pkgName] = data;
  return data;
}

export function inputTemplate(details, params, startParam = {}) {
  const out = {};

  if(params.length !== details.parameters.length)
    throw new Error('param_length_mismatch');

  const paramObj = details.parameters
    .reduce((out, cur, index) => {
      if(!(cur in out)) out[cur] = params[index];
      return out;
    }, startParam);
  for(let signal of details.signalInputs) {
    out[signal.name] = signal.arraySize
      ? makeArray(evaluateExpression(signal.arraySize, paramObj), 1)
      : signal.busName && signal.busDetails
      ? inputTemplate(signal.busDetails, signal.busParams, paramObj)
      : 1; // dummy value
  }
  return out;
}

// Thanks ChatGPT
function makeArray(length, fill) {
    const result = [];  // Initialize an empty array
    for (let i = 0; i < length; i++) {
        result.push(fill);  // Push the fill value into the array for each iteration
    }
    return result;  // Return the filled array
}

// Thanks ChatGPT
function evaluateExpression(expression, variables) {
    const ops = {
        '+': (a, b) => a + b,
        '-': (a, b) => a - b,
        '*': (a, b) => a * b,
        '/': (a, b) => a / b,
        '%': (a, b) => a % b,
    };

    const precedence = {
        '+': 1,
        '-': 1,
        '*': 2,
        '/': 2,
        '%': 2
    };

    // Tokenize the expression
    const tokens = expression.match(/(?:[a-z0-9_]+|\d+|[+*/%-])/gi);

    // Stack for values and operators
    const values = [];
    const operators = [];

    // Helper function to perform operation based on precedence
    const applyOperator = (operator, second, first) => {
        if (operator in ops) {
            return ops[operator](first, second);
        }
        throw new Error('Unsupported operator ' + operator);
    };

    // Handle each token
    tokens.forEach(token => {
        if (!isNaN(token)) {
            // Push number directly to values stack
            values.push(parseInt(token, 10));
        } else if (token in variables) {
            // Replace token with corresponding variable value
            values.push(evaluateExpression(variables[token], {}));
        } else if (token in ops) {
            // Apply all operators with higher or equal precedence
            while (operators.length !== 0 && precedence[operators[operators.length - 1]] >= precedence[token]) {
                values.push(applyOperator(operators.pop(), values.pop(), values.pop()));
            }
            // Push current operator to stack
            operators.push(token);
        } else {
            throw new Error('Invalid token: ' + token);
        }
    });

    // Apply remaining operators
    while (operators.length !== 0) {
        values.push(applyOperator(operators.pop(), values.pop(), values.pop()));
    }

    // The final value on the stack is the result
    return values.pop();
}

#!/usr/bin/env node
// Aided with basic GitHub coding tools

/**
 * WikiFlow Code Quality CLI
 *
 * A powerful CLI for maintaining code quality in the WikiFlow 2025 project.
 * Run with --help to see available options.
 */

const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');
const readline = require('readline');

// Terminal colors for better output
const colors = {
  reset: '\x1b[0m',
  bright: '\x1b[1m',
  dim: '\x1b[2m',
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  magenta: '\x1b[35m',
  cyan: '\x1b[36m',
};

const args = process.argv.slice(2);
const helpRequested = args.includes('--help') || args.includes('-h');
const fixMode = args.includes('--fix') || args.includes('-f');
const strictMode = args.includes('--strict') || args.includes('-s');
const verboseMode = args.includes('--verbose') || args.includes('-v');
const typeCheck = args.includes('--type-check') || args.includes('-t');
const lintOnly = args.includes('--lint-only');
const formatOnly = args.includes('--format-only');
const noEmoji = args.includes('--no-emoji');

// Customized emojis for better UX
const emojis = noEmoji
  ? {
      check: '[OK]',
      error: '[ERROR]',
      warning: '[WARN]',
      info: '[INFO]',
      rocket: '[STARTED]',
      sparkles: '[DONE]',
    }
  : {
      check: '✅',
      error: '❌',
      warning: '⚠️',
      info: 'ℹ️',
      rocket: '🚀',
      sparkles: '✨',
    };

/**
 * Display help message
 */
function showHelp() {
  console.log(`${colors.bright}${colors.cyan}WikiFlow Code Quality CLI${colors.reset}

A tool for maintaining code quality in the WikiFlow 2025 project.

${colors.bright}Usage:${colors.reset}
  node code-quality.js [options]

${colors.bright}Options:${colors.reset}
  -h, --help       Show this help message
  -f, --fix        Automatically fix issues when possible
  -s, --strict     Enable strict mode (treat warnings as errors)
  -v, --verbose    Show detailed output
  -t, --type-check Run TypeScript type checking
  --lint-only      Only run ESLint (skip Prettier)
  --format-only    Only run Prettier (skip ESLint)
  --no-emoji       Display without emojis

${colors.bright}Examples:${colors.reset}
  node code-quality.js                Run all checks
  node code-quality.js --fix          Fix issues automatically
  node code-quality.js --strict       Fail on warnings
  node code-quality.js --lint-only    Only run linting checks
  `);
  process.exit(0);
}

if (helpRequested) {
  showHelp();
}

/**
 * Execute a command and handle errors
 * @param {string} command - The command to execute
 * @param {string} errorMessage - The message to display on error
 * @param {boolean} ignoreErrors - Whether to continue on error
 * @returns {string} - The command output
 */
function execCommand(command, errorMessage, ignoreErrors = false) {
  try {
    if (verboseMode) {
      console.log(`${colors.dim}> ${command}${colors.reset}`);
    }
    const output = execSync(command, { encoding: 'utf8' });
    return output;
  } catch (error) {
    if (!ignoreErrors) {
      console.error(`${emojis.error} ${colors.red}${errorMessage}${colors.reset}`);
      if (verboseMode) {
        console.error(`${colors.dim}${error.message}${colors.reset}`);
      }
      if (strictMode) {
        process.exit(1);
      }
    }
    return error.output?.toString() || '';
  }
}

/**
 * Check if a dependency is installed
 * @param {string} packageName - The package to check
 * @returns {boolean} - Whether the package is installed
 */
function isPackageInstalled(packageName) {
  try {
    require.resolve(packageName, { paths: [process.cwd()] });
    return true;
  } catch (e) {
    return false;
  }
}

/**
 * Main function to run checks
 */
async function runChecks() {
  console.log(
    `${emojis.rocket} ${colors.bright}${colors.blue}Running WikiFlow Code Quality Checks${colors.reset}\n`
  );

  let eslintIssues = 0;
  let prettierIssues = 0;
  let typeIssues = 0;

  // Check TypeScript types
  if (typeCheck) {
    console.log(`${emojis.info} ${colors.cyan}Running TypeScript type checking...${colors.reset}`);

    try {
      execSync('npx tsc --noEmit', { stdio: verboseMode ? 'inherit' : 'pipe' });
      console.log(`${emojis.check} ${colors.green}TypeScript types are valid${colors.reset}`);
    } catch (error) {
      typeIssues++;
      console.error(`${emojis.error} ${colors.red}TypeScript type issues found${colors.reset}`);
      if (verboseMode) {
        console.error(error.stdout?.toString());
      } else {
        console.error(`  ${colors.yellow}Run with --verbose to see details${colors.reset}`);
      }
    }
  }

  // Run ESLint if not format-only
  if (!formatOnly) {
    if (!isPackageInstalled('eslint')) {
      console.error(
        `${emojis.error} ${colors.red}ESLint is not installed. Skipping linting.${colors.reset}`
      );
    } else {
      console.log(`${emojis.info} ${colors.cyan}Running ESLint...${colors.reset}`);

      const eslintCommand = fixMode
        ? 'npx eslint --ext .js,.jsx,.ts,.tsx src/ --fix'
        : 'npx eslint --ext .js,.jsx,.ts,.tsx src/';

      try {
        execSync(eslintCommand, { stdio: verboseMode ? 'inherit' : 'pipe' });
        console.log(`${emojis.check} ${colors.green}No ESLint issues found${colors.reset}`);
      } catch (error) {
        eslintIssues++;
        console.error(`${emojis.error} ${colors.red}ESLint issues found${colors.reset}`);
        if (!verboseMode && !fixMode) {
          console.error(
            `  ${colors.yellow}Run with --fix to automatically fix issues${colors.reset}`
          );
        }
      }
    }
  }

  // Run Prettier if not lint-only
  if (!lintOnly) {
    if (!isPackageInstalled('prettier')) {
      console.error(
        `${emojis.error} ${colors.red}Prettier is not installed. Skipping formatting.${colors.reset}`
      );
    } else {
      console.log(`${emojis.info} ${colors.cyan}Running Prettier...${colors.reset}`);

      const prettierCheckCommand = 'npx prettier --check "src/**/*.{js,jsx,ts,tsx,json,css,md}"';
      const prettierWriteCommand = 'npx prettier --write "src/**/*.{js,jsx,ts,tsx,json,css,md}"';

      if (fixMode) {
        const output = execCommand(
          prettierWriteCommand,
          'Error while formatting files with Prettier'
        );
        console.log(`${emojis.check} ${colors.green}Files formatted with Prettier${colors.reset}`);
      } else {
        try {
          execSync(prettierCheckCommand, { stdio: verboseMode ? 'inherit' : 'pipe' });
          console.log(
            `${emojis.check} ${colors.green}All files are properly formatted${colors.reset}`
          );
        } catch (error) {
          prettierIssues++;
          console.error(`${emojis.error} ${colors.red}Formatting issues found${colors.reset}`);
          if (!verboseMode) {
            console.error(
              `  ${colors.yellow}Run with --fix to automatically fix issues${colors.reset}`
            );
          }
        }
      }
    }
  }

  // Summary
  console.log(
    `\n${emojis.sparkles} ${colors.bright}${colors.blue}WikiFlow Code Quality Check Summary${colors.reset}`
  );

  const totalIssues = eslintIssues + prettierIssues + typeIssues;
  if (totalIssues === 0) {
    console.log(`${emojis.check} ${colors.green}All checks passed successfully!${colors.reset}`);
  } else {
    console.log(`${emojis.warning} ${colors.yellow}Issues found:${colors.reset}`);
    if (eslintIssues > 0)
      console.log(`  ${colors.yellow}- ESLint issues: ${eslintIssues}${colors.reset}`);
    if (prettierIssues > 0)
      console.log(`  ${colors.yellow}- Prettier issues: ${prettierIssues}${colors.reset}`);
    if (typeIssues > 0)
      console.log(`  ${colors.yellow}- TypeScript issues: ${typeIssues}${colors.reset}`);

    if (fixMode) {
      console.log(
        `${emojis.info} ${colors.cyan}Some issues were automatically fixed. Re-run to check remaining issues.${colors.reset}`
      );
    } else {
      console.log(
        `${emojis.info} ${colors.cyan}Run with --fix to automatically fix some issues.${colors.reset}`
      );
    }

    if (strictMode) {
      console.error(
        `${emojis.error} ${colors.red}Strict mode enabled. Exiting with error.${colors.reset}`
      );
      process.exit(1);
    }
  }
}

// Run the main function
runChecks().catch(error => {
  console.error(`${emojis.error} ${colors.red}Unexpected error:${colors.reset}`, error);
  process.exit(1);
});

"ui";
