const steem = require('steem');

var delegation_transactions = [];

function loadDelegations(account, callback) {
  getTransactions(account, -1, callback);
}

function getTransactions(account, start, callback) {
  var last_trans = start;

  steem.api.getAccountHistory(account, start, (start < 0) ? 10000 : Math.min(start, 10000), function (err, result) {
    if(err) {
      console.log(err);
      return;
    }

    result.reverse();

    result.forEach(function(trans) {
      var op = trans[1].op;

      if(op[0] == 'delegate_vesting_shares' && op[1].delegatee == account)
        delegation_transactions.push({ id: trans[0], data: op[1] });

      // Save the ID of the last transaction that was processed.
      last_trans = trans[0];
    });

    if(last_trans > 0)
      getTransactions(account, last_trans, callback);
    else
      processDelegations(callback);
  });
}

function processDelegations(callback) {
  var delegations = [];

  // Go through the delegation transactions from oldest to newest to find the final delegated amount from each account
  delegation_transactions.reverse();

  for(var i = 0; i < delegation_transactions.length; i++) {
    var trans = delegation_transactions[i];

    // Check if this is a new delegation or an update to an existing delegation from this account
    var delegation = delegations.find(d => d.delegator == trans.data.delegator);

    if(delegation) {
      delegation.vesting_shares = trans.data.vesting_shares;
    } else {
      delegations.push({ delegator: trans.data.delegator, vesting_shares: trans.data.vesting_shares });
    }
  }

  delegation_transactions = [];

  // Return a list of all delegations (and filter out any that are 0)
  if(callback)
    callback(delegations.filter(function(d) { return parseFloat(d.vesting_shares) > 0; }));
}

module.exports = {
  loadDelegations: loadDelegations
}

const fs = require('fs')
const readline = require('readline')
const { google } = require('googleapis')
const dateFns = require('date-fns')
const { exec } = require('child_process')
const path = require('path')

/*
  Note: This file was first Designed via basic programming aids and then modified by tbc
*/

const SCOPES = ['https://www.googleapis.com/auth/calendar.readonly']
const TOKEN_PATH = path.join(__dirname, 'token.json')
const CREDENTIALS_PATH = path.join(__dirname, 'credentials.json')
const APPLESCRIPT_TEMPLATE_PATH = path.join(__dirname, 'apple-script.template')
const OPTIONAL_CALENDAR_ID_PATH = path.join(__dirname, 'calendar.id')
const APPLESCRIPT_TEMPLATE = fs.readFileSync(APPLESCRIPT_TEMPLATE_PATH, 'utf-8')
const OPTIONAL_CALENDAR_ID = fs.existsSync(OPTIONAL_CALENDAR_ID_PATH) && fs.readFileSync(OPTIONAL_CALENDAR_ID_PATH, 'utf-8').trim()
const NEXT_MEETING_PATH = path.join(__dirname, 'next-meeting.scpt')

fs.readFile(CREDENTIALS_PATH, async (err, content) => {
  if (err) return console.log('Error loading client secret file:', err)
  authorize(JSON.parse(content), runForever)
})

function authorize(credentials, callback) {
  const { client_secret, client_id, redirect_uris } = credentials.installed
  const oAuth2Client = new google.auth.OAuth2(client_id, client_secret, redirect_uris[0])

  fs.readFile(TOKEN_PATH, (err, token) => {
    if (err) return getAccessToken(oAuth2Client, callback)
    oAuth2Client.setCredentials(JSON.parse(token))
    callback(oAuth2Client)
  })
}

function getAccessToken(oAuth2Client, callback) {
  const authUrl = oAuth2Client.generateAuthUrl({
    access_type: 'offline',
    scope: SCOPES,
  })
  console.log('Authorize this app by visiting this url:', authUrl)
  const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout,
  })
  rl.question('Enter the code from that page here: ', (code) => {
    rl.close()
    oAuth2Client.getToken(code, (err, token) => {
      if (err) return console.error('Error retrieving access token', err)
      oAuth2Client.setCredentials(token)

      fs.writeFile(TOKEN_PATH, JSON.stringify(token), (err) => {
        if (err) return console.error(err)
        console.log('Token stored to', TOKEN_PATH)
      })
      callback(oAuth2Client)
    })
  })
}

let joinedMeetings = []

async function runForever (auth) {
  while (true) {
    try {
      lookForNextEventAndJoin(auth)
    } catch (err) {
      console.log(err)
    }
    await new Promise(resolve => setTimeout(resolve, 5000))
  }
}

async function lookForNextEventAndJoin (auth) {
  const calendar = google.calendar({ version: 'v3', auth })
  const { data: { items: [nextEvent] } } = await calendar.events.list({
    calendarId: OPTIONAL_CALENDAR_ID || 'primary',
    timeMin: (new Date()).toISOString(),
    maxResults: 1,
    singleEvents: true,
    orderBy: 'startTime',
  })
  if (!nextEvent) return
  const startAsDate = dateFns.parseISO(nextEvent.start.dateTime || nextEvent.start.date)
  const endAsDate = dateFns.parseISO(nextEvent.end.dateTime || nextEvent.end.date)
  const secondsUntil = dateFns.differenceInSeconds(startAsDate, new Date())
  const meetingDurationInSeconds = dateFns.differenceInSeconds(endAsDate, startAsDate)
  const meetingUrl = nextEvent.conferenceData?.entryPoints[0]?.uri
  const meetingUniqueId = `${nextEvent.id}-${nextEvent.start.dateTime}`
  const meetingSummary = nextEvent.summary.replace(/[^\x00-\x7F]/g, '')
  const hasAlreadyJoinedMeeting = joinedMeetings.includes(meetingUniqueId)
  const shouldJoinMeeting = meetingUrl && !hasAlreadyJoinedMeeting && secondsUntil < 10
  if (shouldJoinMeeting) {
    joinedMeetings.push(meetingUniqueId)
    const script = APPLESCRIPT_TEMPLATE
      .replace('MEETING_URL', meetingUrl)
      .replace('MEETING_TIME_IN_SECONDS', meetingDurationInSeconds + secondsUntil)
      .replace('MEETING_SUMMARY', meetingSummary)
    fs.writeFileSync(NEXT_MEETING_PATH, script)
    exec(`osascript ${NEXT_MEETING_PATH}`, () => { /* noop */ })
    console.log(`[${new Date().toISOString()}] Joining ${nextEvent.summary} ${meetingUrl}`)
  }
}

// Aided with basic GitHub coding tools
import React, { useState, useEffect } from "react";
import {
  getAllBooks,
  updateProgress,
  deleteBook,
  addBook,
} from "../services/bookService";
import BookCard from "../components/BookCard";

const HomePage = () => {
  // 状態管理
  const [books, setBooks] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  // 書籍追加モーダル用の状態
  const [showAddModal, setShowAddModal] = useState(false);
  const [formData, setFormData] = useState({
    title: "",
    author: "",
    totalPages: 0,
    currentPage: 0,
    memo: "",
  });
  const [formErrors, setFormErrors] = useState({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [addSuccess, setAddSuccess] = useState("");
  // 書籍データを読み込む
  useEffect(() => {
    const loadBooks = async () => {
      setLoading(true);
      try {
        const result = await getAllBooks();
        if (result.success) {
          setBooks(result.books);
          setError("");
        } else {
          console.error("書籍データの読み込みエラー:", result.message);
          setBooks([]);
          setError(result.message);
        }
      } catch (err) {
        console.error("書籍データの読み込み例外:", err);
        setBooks([]);
        setError("データの読み込み中にエラーが発生しました");
      } finally {
        setLoading(false);
      }
    };

    loadBooks();
  }, []);
  // 書籍を削除する関数
  const handleDeleteBook = async (id) => {
    // 確認ダイアログを表示
    if (window.confirm("この書籍を削除してもよろしいですか？")) {
      try {
        const result = await deleteBook(id);
        if (result.success) {
          // 画面上の書籍リストを更新
          setBooks(books.filter((book) => book.id !== id));
        } else {
          alert(result.message);
        }
      } catch (err) {
        console.error("書籍削除エラー:", err);
        alert("書籍の削除中にエラーが発生しました");
      }
    }
  };

  // 読書進捗を更新する関数
  const handleUpdateProgress = async (id, newPage) => {
    // 数値以外の入力は無視
    const pageNumber = parseInt(newPage, 10);
    if (isNaN(pageNumber)) return;

    try {
      // サービスを使用して更新
      const result = await updateProgress(id, pageNumber);

      if (result.success) {
        // 書籍リストを更新
        setBooks((prevBooks) =>
          prevBooks.map((book) => (book.id === id ? result.book : book))
        );
        // 結果を返す（BookCardコンポーネントが使用）
        return result;
      } else {
        alert(result.message);
        return { success: false };
      }
    } catch (err) {
      console.error("進捗更新エラー:", err);
      alert("進捗の更新中にエラーが発生しました");
      return { success: false };
    }
  };

  // 書籍リスト（フィルタリングなし）
  const filteredBooks = books;

  // プラスボタンの処理（総ページ数）
  const handleIncrementTotalPages = () => {
    const currentValue =
      formData.totalPages === "" || formData.totalPages === 0
        ? 0
        : parseInt(formData.totalPages, 10);
    const newValue = currentValue + 1;
    setFormData({
      ...formData,
      totalPages: newValue,
    });
  };

  // マイナスボタンの処理（総ページ数）
  const handleDecrementTotalPages = () => {
    const currentValue =
      formData.totalPages === "" || formData.totalPages === 0
        ? 0
        : parseInt(formData.totalPages, 10);
    // 1より小さくならないようにする
    const newValue = Math.max(1, currentValue - 1);
    setFormData({
      ...formData,
      totalPages: newValue,
    });
  };

  // プラスボタンの処理（現在のページ）
  const handleIncrementCurrentPage = () => {
    const currentValue =
      formData.currentPage === "" || formData.currentPage === 0
        ? 0
        : parseInt(formData.currentPage, 10);
    const totalPages =
      formData.totalPages === "" || formData.totalPages === 0
        ? 0
        : parseInt(formData.totalPages, 10);
    // 総ページ数より大きくならないようにする
    const newValue = Math.min(currentValue + 1, totalPages);
    setFormData({
      ...formData,
      currentPage: newValue,
    });
  };

  // マイナスボタンの処理（現在のページ）
  const handleDecrementCurrentPage = () => {
    const currentValue =
      formData.currentPage === "" || formData.currentPage === 0
        ? 0
        : parseInt(formData.currentPage, 10);
    // 0より小さくならないようにする
    const newValue = Math.max(0, currentValue - 1);
    setFormData({
      ...formData,
      currentPage: newValue,
    });
  };

  // フォーム入力変更ハンドラー
  const handleInputChange = (e) => {
    const { name, value } = e.target;

    let processedValue = value;

    if (name === "totalPages" || name === "currentPage") {
      // 空文字列の場合はそのまま（削除操作を許可するため）
      if (value === "") {
        processedValue = 0;
      } else {
        // 数値以外の文字を除去
        const numericValue = value.replace(/[^\d]/g, "");

        // 数値に変換
        processedValue = numericValue ? parseInt(numericValue, 10) : 0;
      }
    }

    setFormData({
      ...formData,
      [name]: processedValue,
    });
  };

  // フォーム送信ハンドラー
  const handleSubmit = async (e) => {
    e.preventDefault();

    // バリデーション
    const newErrors = {};
    if (!formData.title.trim()) {
      newErrors.title = "タイトルは必須です";
    }

    // 著者名の入力は任意に変更
    // if (!formData.author.trim()) {
    //   newErrors.author = "著者名は必須です";
    // }

    if (formData.totalPages <= 0) {
      newErrors.totalPages = "有効なページ数を入力してください";
    }

    if (formData.currentPage < 0) {
      newErrors.currentPage = "現在のページは0以上である必要があります";
    }

    if (formData.currentPage > formData.totalPages) {
      newErrors.currentPage =
        "現在のページは総ページ数を超えることはできません";
    }

    // エラーがあれば更新して関数を終了
    if (Object.keys(newErrors).length > 0) {
      setFormErrors(newErrors);
      return;
    }

    // エラーをリセット
    setFormErrors({});
    setIsSubmitting(true);

    try {
      // BookServiceを使用して書籍を追加（非同期処理）
      const result = await addBook(formData);

      if (result.success) {
        // 成功メッセージを表示
        setAddSuccess("書籍が追加されました！");

        // 書籍リストを更新
        const updatedResult = await getAllBooks();
        if (updatedResult.success) {
          setBooks(updatedResult.books);
        }

        // フォームをリセット
        setFormData({
          title: "",
          author: "",
          totalPages: 0,
          currentPage: 0,
          memo: "",
        });

        // モーダルを閉じる（2秒後）
        setTimeout(() => {
          setShowAddModal(false);
          setAddSuccess("");
        }, 2000);
      } else {
        // エラーメッセージを表示
        setFormErrors({
          submit:
            result.message ||
            "データの保存中にエラーが発生しました。もう一度お試しください。",
        });
      }
    } catch (error) {
      console.error("書籍追加エラー:", error);
      setFormErrors({
        submit: "エラーが発生しました。ネットワーク接続を確認してください。",
      });
    } finally {
      setIsSubmitting(false);
    }
  };

  // モーダルの外側クリックでモーダルを閉じる
  const handleOutsideClick = (e) => {
    if (e.target.className === "add-book-modal-overlay") {
      setShowAddModal(false);
    }
  };

  // 書籍追加モーダルをレンダリング
  const renderAddBookModal = () => (
    <div className="add-book-modal-overlay" onClick={handleOutsideClick}>
      <div className="add-book-modal">
        <button
          className="close-modal-btn"
          onClick={() => setShowAddModal(false)}
        >
          ×
        </button>

        <h2>新しい書籍を追加</h2>

        {addSuccess && <div className="success-message">{addSuccess}</div>}
        {formErrors.submit && (
          <div className="error-message">{formErrors.submit}</div>
        )}

        <form onSubmit={handleSubmit}>
          <div className="form-group">
            <label htmlFor="title">
              タイトル <span className="required">*</span>
            </label>
            <input
              type="text"
              id="title"
              name="title"
              value={formData.title}
              onChange={handleInputChange}
              className={formErrors.title ? "error" : ""}
              disabled={isSubmitting}
            />
            {formErrors.title && (
              <p className="error-text">{formErrors.title}</p>
            )}
          </div>{" "}
          <div className="form-group">
            <label htmlFor="author">著者</label>
            <input
              type="text"
              id="author"
              name="author"
              value={formData.author}
              onChange={handleInputChange}
              className={formErrors.author ? "error" : ""}
              disabled={isSubmitting}
            />
            {formErrors.author && (
              <p className="error-text">{formErrors.author}</p>
            )}
          </div>
          <div className="form-group">
            <label htmlFor="totalPages">
              総ページ数 <span className="required">*</span>
            </label>
            <div className="progress-input">
              <button
                type="button"
                className="page-control-btn page-decrement-btn"
                onClick={handleDecrementTotalPages}
                disabled={
                  !formData.totalPages ||
                  formData.totalPages <= 1 ||
                  isSubmitting
                }
              >
                －
              </button>
              <input
                type="text"
                id="totalPages"
                name="totalPages"
                value={formData.totalPages}
                onChange={handleInputChange}
                inputMode="numeric"
                className={formErrors.totalPages ? "error" : ""}
                disabled={isSubmitting}
                placeholder="0"
              />
              <button
                type="button"
                className="page-control-btn page-increment-btn"
                onClick={handleIncrementTotalPages}
                disabled={isSubmitting}
              >
                ＋
              </button>
            </div>
            {formErrors.totalPages && (
              <p className="error-text">{formErrors.totalPages}</p>
            )}
          </div>
          <div className="form-group">
            <label htmlFor="currentPage">現在のページ</label>
            <div className="progress-input">
              <button
                type="button"
                className="page-control-btn page-decrement-btn"
                onClick={handleDecrementCurrentPage}
                disabled={
                  !formData.currentPage ||
                  formData.currentPage <= 0 ||
                  isSubmitting
                }
              >
                －
              </button>
              <input
                type="text"
                id="currentPage"
                name="currentPage"
                value={formData.currentPage}
                onChange={handleInputChange}
                inputMode="numeric"
                className={formErrors.currentPage ? "error" : ""}
                disabled={isSubmitting}
                placeholder="0"
              />
              <button
                type="button"
                className="page-control-btn page-increment-btn"
                onClick={handleIncrementCurrentPage}
                disabled={
                  !formData.totalPages ||
                  (formData.currentPage !== 0 &&
                    formData.currentPage >= formData.totalPages) ||
                  isSubmitting
                }
              >
                ＋
              </button>
              {formData.totalPages > 0 && <span>/ {formData.totalPages}</span>}
            </div>
            {formErrors.currentPage && (
              <p className="error-text">{formErrors.currentPage}</p>
            )}
          </div>
          <div className="form-group">
            <label htmlFor="memo">メモ（任意）</label>
            <textarea
              id="memo"
              name="memo"
              value={formData.memo}
              onChange={handleInputChange}
              rows="3"
              disabled={isSubmitting}
            />
          </div>
          <div className="form-actions">
            <button type="submit" className="btn" disabled={isSubmitting}>
              {isSubmitting ? "追加中..." : "書籍を追加"}
            </button>
            <button
              type="button"
              className="btn btn-secondary"
              onClick={() => setShowAddModal(false)}
              disabled={isSubmitting}
            >
              キャンセル
            </button>
          </div>
        </form>
      </div>
    </div>
  );

  return (
    <div>
      <h2 className="page-title">書籍リスト</h2> {/* 追加ボタン */}
      <div className="book-list-actions">
        <button
          className="btn add-book-btn"
          onClick={() => setShowAddModal(true)}
        >
          + 新しい書籍を追加
        </button>
      </div>
      {loading ? (
        <p className="loading-message">読み込み中...</p>
      ) : error ? (
        <div className="error-state">
          <p className="error-message">{error}</p>
          <button className="btn" onClick={() => window.location.reload()}>
            再読み込み
          </button>
        </div>
      ) : filteredBooks.length > 0 ? (
        <div className="books-grid">
          {filteredBooks.map((book) => (
            <BookCard
              key={book.id}
              book={book}
              onUpdateProgress={handleUpdateProgress}
              onDelete={handleDeleteBook}
            />
          ))}
        </div>
      ) : (
        <div className="empty-state">
          <h3>書籍がありません</h3>
          <p>新しい書籍を追加してみましょう！</p>
          <button className="btn" onClick={() => setShowAddModal(true)}>
            書籍を追加
          </button>
        </div>
      )}
      {/* 書籍追加モーダル */}
      {showAddModal && renderAddBookModal()}
    </div>
  );
};

export default HomePage;

