/**
 * https://stackoverflow.com/questions/6150289/how-can-i-convert-an-image-into-base64-string-using-javascript
 * @param {string} url
 * @param {Function} callback
 */
function toDataURLviaXHR(url, callback) {
    var xhr = new XMLHttpRequest();
    xhr.onload = function () {
        var reader = new FileReader();
        reader.onloadend = function () {
            callback(reader.result);
        };
        reader.readAsDataURL(xhr.response);
    };
    xhr.open("GET", url);
    xhr.responseType = "blob";
    xhr.send();
}

/**
 * @param {Blob} arrayBuffer
 * @param {Function} callback
 * @returns base64text
 */
function fileReaderToDataURL(arrayBuffer, callback) {
    var reader = new FileReader();
    reader.onloadend = function () {
        callback(reader.result);
    };
    reader.readAsDataURL(arrayBuffer);
}

/**
* @param {string} url
* @param {Function} callback
* @returns base64text
*/
async function urlToDataURL(url, callback) {
    var dataArray = await (await fetch(url)).arrayBuffer();
    var dataBytes = new Uint8Array(dataArray);
    var blob = new Blob([dataBytes]);

    return fileReaderToDataURL(blob, callback)
}

/**
 * code Built using basic development resources3.5
 * also ref:  
 * https://stackoverflow.com/questions/19183180/how-to-save-an-image-to-localstorage-and-display-it-on-the-next-page
 * https://stackoverflow.com/questions/22710627/tainted-canvases-may-not-be-exported
 * @param {string} imgSelector 
 * @param {*} callback 
 */
function imgDomToDataURL(imgSelector, callback) {
    // Get the reference to the image element
    var img = document.querySelector(imgSelector);

    // Create a canvas element
    var canvas = document.createElement('canvas');
    var ctx = canvas.getContext('2d');

    // Set canvas dimensions to match the image
    canvas.width = img.width;
    canvas.height = img.height;

    // Draw the image onto the canvas
    ctx.drawImage(img, 0, 0);

    // Get the data URI of the image
    var dataURI = canvas.toDataURL();

    // Set the data URI as the new src for the image element
    // img.src = dataURI;
    callback(dataURI);

    // Optionally, you can remove the src attribute to prevent the browser from loading the image from its original URL
    // img.removeAttribute('src');
}
/**
 * code generated by github copliot
 * @param {string} imgUrl 
 * @param {*} callback 
 */
function imgUrlToDataURL(imgUrl, callback) {

    // Create a new image element
    var img = new Image();
    img.crossOrigin = "anonymous"

    // Set the source of the image element to the imgUrl
    img.src = imgUrl;

    // Wait for the image to load
    img.onload = function() {
        // Create a canvas element
        var canvas = document.createElement('canvas');
        var ctx = canvas.getContext('2d');

        // Set canvas dimensions to match the image
        canvas.width = img.width;
        canvas.height = img.height;

        // Draw the image onto the canvas
        ctx.drawImage(img, 0, 0);

        // Get the data URI of the image
        var dataURI = canvas.toDataURL();

        // Set the data URI as the new src for the image element
        // img.src = dataURI;
        callback(dataURI);

        // Optionally, you can remove the src attribute to prevent the browser from loading the image from its original URL
        // img.removeAttribute('src');
    };
}


export {
    urlToDataURL,
    fileReaderToDataURL,
    imgDomToDataURL,
    imgUrlToDataURL,
}

import api from './api';

/**
 * Serviço para gerenciar faturamento e finanças
 * Fornece funções para acessar e analisar dados financeiros
 * Aided with basic GitHub coding tools
 */
export const billingService = {
  /**
   * Busca todas as faturas cadastradas no sistema
   * @returns {Promise} Promise com a lista de faturas
   */
  getAllInvoices: async () => {
    const response = await api.get('/faturas');
    return response.data;
  },

  /**
   * Busca uma fatura específica pelo ID
   * @param {number} id - ID da fatura a ser buscada
   * @returns {Promise} Promise com os dados da fatura
   */
  getInvoiceById: async (id) => {
    const response = await api.get(`/faturas/${id}`);
    return response.data;
  },

  /**
   * Busca faturamento agrupado por período
   * @param {string} startDate - Data inicial do período (formato: YYYY-MM-DD)
   * @param {string} endDate - Data final do período (formato: YYYY-MM-DD)
   * @param {string} groupBy - Como agrupar os dados (dia, mes, ano)
   * @returns {Promise} Promise com os dados de faturamento agrupados
   */
  getBillingByPeriod: async (startDate, endDate, groupBy = 'dia') => {
    const response = await api.get('/faturas/faturamento', {
      params: { startDate, endDate, groupBy }
    });
    return response.data;
  },

  /**
   * Busca o faturamento do mês atual
   * @returns {Promise} Promise com os dados de faturamento do mês atual
   */
  getCurrentMonthBilling: async () => {
    const response = await api.get('/faturas/faturamento/mes-atual');
    return response.data;
  },

  /**
   * Calcula o gasto médio por paciente
   * @returns {Promise} Promise com o valor médio gasto por paciente
   */
  getAverageSpendingPerPatient: async () => {
    const response = await api.get('/faturas/media-por-paciente');
    return response.data;
  },

  /**
   * Busca as faturas associadas a um paciente específico
   * @param {number} patientId - ID do paciente
   * @returns {Promise} Promise com a lista de faturas do paciente
   */
  getInvoicesByPatient: async (patientId) => {
    const response = await api.get(`/faturas/paciente/${patientId}`);
    return response.data;
  }
};

